local a=require("ui.panels.fcs")local b={}local function c(d)return math.floor((d or 0)+0.5)end;function b.modeText(e)if e==nil then return"--/----"end;return(a.MODE_LABEL[e]or tostring(e)).."/----"end;function b.spdText(f)if type(f)~="number"then return"--ms"end;return tostring(c(f)).."ms"end;function b.loopText(g,h)if h=="hz"then if type(g)~="number"or g<=0 then return"--ms"end;return tostring(c(1000/g)).."ms"end;if type(g)~="number"then return"--ms"end;return tostring(c(g)).."ms"end;function b.gpsSig(i,j)if not j or type(i)~="number"then return"----"end;if i>=0.75 then return"GOOD"end;if i>=0.4 then return"FAIR"end;return"POOR"end;function b.values(k)k=k or{}local l=a.fieldValues(k)return{MODE=b.modeText(k.flightMode),ALT=l.ALT.."m",TRUSPD=b.spdText(k.tas),VSPD=l.VSPD.."ms",HDG=l.HDG.."deg",FCS=l.LINK=="UP"and"OP"or"NO-OP",GNDSAF=k.gndSafety and"ON"or"OFF",PROXWRN="OFF",FCSLOOP=b.loopText(k.loopHz,"hz"),UILOOP=b.loopText(k.uiLoopMs,"ms"),NAVLOOP=b.loopText(k.navLoopMs,"ms"),APLOOP="--ms",DEVWRN=k.devWarn and"ON"or"OFF",GPSSIG=b.gpsSig(k.gpsQuality,k.gpsFixOk),APMODE="IDLE",DSKFCS=k.diskFcs and"YES"or"NO",DSKNAV=k.diskNav and"YES"or"NO"}end;return b